"""Trusted namespace entry retains subreaper custody through helper exit.

The outer native guardian still enforces the original deadline, orphan rejection
and actual Q/EOF/reap. No original lease reaches the launched workload.
"""

ENTER_VIEW = "import os,sys,ctypes,subprocess,signal\nview,mount,user=map(int,sys.argv[1:4])\nos.setns(user,0)\nos.setns(mount,0)\nroot=os.open('..',os.O_RDONLY|os.O_DIRECTORY,dir_fd=view)\nexpected=os.fstat(view);actual=os.stat('view',dir_fd=root)\nassert (expected.st_dev,expected.st_ino)==(actual.st_dev,actual.st_ino)\nos.fchdir(root);os.chroot('.');os.chdir('/')\nfor descriptor in (view,mount,user,root):os.close(descriptor)\nlibc=ctypes.CDLL(None,use_errno=True)\nassert libc.prctl(36,1,0,0,0)==0\nenabled=ctypes.c_int()\nassert libc.prctl(37,ctypes.byref(enabled),0,0,0)==0 and enabled.value==1\nprogram=subprocess.Popen(sys.argv[4:],close_fds=True)\ncode=program.wait()\nwhile True:\n try:os.waitid(os.P_ALL,0,os.WEXITED)\n except ChildProcessError:break\nif code<0:\n number=-code\n if number not in (signal.SIGKILL,signal.SIGSTOP):signal.signal(number,signal.SIG_DFL)\n os.kill(os.getpid(),number)\nos._exit(code if code>=0 else 128-code)\n"

ENTER_NETWORK_VIEW = "import os,sys,ctypes,subprocess,signal\nview,mount,user,network=map(int,sys.argv[1:5])\nos.setns(user,0)\nos.setns(network,0)\nos.setns(mount,0)\nroot=os.open('..',os.O_RDONLY|os.O_DIRECTORY,dir_fd=view)\nexpected=os.fstat(view);actual=os.stat('view',dir_fd=root)\nassert (expected.st_dev,expected.st_ino)==(actual.st_dev,actual.st_ino)\nos.fchdir(root);os.chroot('.');os.chdir('/')\nfor descriptor in (view,mount,user,network,root):os.close(descriptor)\nlibc=ctypes.CDLL(None,use_errno=True)\nassert libc.prctl(36,1,0,0,0)==0\nenabled=ctypes.c_int()\nassert libc.prctl(37,ctypes.byref(enabled),0,0,0)==0 and enabled.value==1\nprogram=subprocess.Popen(sys.argv[5:],close_fds=True)\ncode=program.wait()\nwhile True:\n try:os.waitid(os.P_ALL,0,os.WEXITED)\n except ChildProcessError:break\nif code<0:\n number=-code\n if number not in (signal.SIGKILL,signal.SIGSTOP):signal.signal(number,signal.SIG_DFL)\n os.kill(os.getpid(),number)\nos._exit(code if code>=0 else 128-code)\n"
